functions.showEli5App:
function showEli5App() {
  var out = document.getElementById("output");
  out.innerHTML = "";
  out.classList.remove("hidden");
  var header = createConfigHeader("SIMPLIFICATION ENGINE", "🧸", "ELI5: Explain It");
  out.appendChild(header);
  var container = document.createElement("div");
  container.style.padding = "0 15px 20px 15px";
  container.innerHTML = `
    <div class="tool-box slide-in" style="padding:15px; border-left:5px solid #1565c0; background:white; border-radius:0px; margin-bottom:15px;">
        <div class="eli-label-sm" style="color:#1565c0;">1. Select Source</div>
        <div style="display:flex; gap:10px; margin-bottom:10px;">
            <label class="checkbox-wrapper" style="flex:1; background:#e3f2fd; padding:10px; border:1px solid #bbdefb; border-radius:4px; cursor:pointer;" onclick="toggleEli5Source('active')">
                <input type="radio" name="eli5Source" value="active" checked style="transform:scale(1.2); margin-right:6px;">
                <span style="font-size:11px; font-weight:700; color:#1565c0;">📄 Active Doc</span>
            </label>
            <label class="checkbox-wrapper" style="flex:1; background:#f5f5f5; padding:10px; border:1px solid #ddd; border-radius:4px; cursor:pointer;" onclick="toggleEli5Source('upload')">
                <input type="radio" name="eli5Source" value="upload" style="transform:scale(1.2); margin-right:6px;">
                <span style="font-size:11px; font-weight:700; color:#546e7a;">📂 Upload File</span>
            </label>
        </div>
        <div id="eli5UploadArea" class="hidden" style="border:2px dashed #90caf9; background:#f0f7ff; padding:15px; text-align:center; cursor:pointer; margin-top:10px;">
            <div style="font-size:20px;">📂</div>
            <div style="font-size:11px; font-weight:bold; color:#1565c0;">Click to Upload PDF or Word</div>
            <div id="eli5FileName" style="font-size:10px; color:#555; margin-top:4px;"></div>
        </div>
        <input type="file" id="eli5FileInput" accept=".docx,.pdf,.txt" class="eli-hidden">
    </div>
    <div class="tool-box slide-in" style="padding:15px; border-left:5px solid #fbc02d; background:white; border-radius:0px; margin-bottom:15px;">
        <div class="eli-row-spread">
            <div class="eli-label-sm" style="color:#ef6c00;">2. Target Audience Age</div>
            <div id="eli5AgeDisplay" style="font-size:14px; font-weight:800; color:#f57f17; background:#fff3e0; padding:2px 8px; border-radius:4px;">14</div>
        </div>
        <input type="range" id="eli5Slider" min="10" max="18" step="4" value="14" style="width:100%; cursor:pointer; margin-bottom:5px;">
        <div style="display:flex; justify-content:space-between; font-size:10px; color:#78909c; font-weight:600;">
            <span>👶 10 (Simple)</span>
            <span>High School (Standard)</span>
            <span>🎓 18 (Detail)</span>
        </div>
        <div id="eli5Desc" style="margin-top:10px; font-size:11px; color:#5d4037; font-style:italic; background:#fff8e1; padding:8px; border-radius:4px;">
            Explains concepts using clear, standard language suitable for a high school student.
        </div>
    </div>
    <div class="tool-box slide-in" style="padding:0; border-left:5px solid #7b1fa2; background:white; border-radius:0px; margin-bottom:15px;">
        <div id="eli5DetailHeader" style="padding:15px; cursor:pointer; display:flex; justify-content:space-between; align-items:center;" onclick="toggleEli5Detail()">
            <div class="eli-label-sm" style="color:#7b1fa2;">3. Depth of Response (Optional)</div>
            <div id="eli5DetailArrow" style="font-size:12px; color:#7b1fa2;">▼</div>
        </div>
        <div id="eli5DetailBody" class="hidden" style="padding:0 15px 15px 15px; border-top:1px solid #f3e5f5;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; margin-top:10px;">
                <div style="font-size:11px; color:#666;">Level of Detail:</div>
                <div id="eli5DetailLabel" style="font-size:11px; font-weight:800; color:#7b1fa2; background:#f3e5f5; padding:2px 8px; border-radius:4px;">Standard</div>
            </div>
            <input type="range" id="eli5DetailSlider" min="1" max="3" step="1" value="1" style="width:100%; cursor:pointer; margin-bottom:5px;">
            <div style="display:flex; justify-content:space-between; font-size:9px; color:#999; font-weight:600;">
                <span>Standard</span>
                <span>Enhanced</span>
                <span>Deep Dive</span>
            </div>
        </div>
    </div>
    <button id="btnRunEli5" class="btn-platinum-config primary" style="width:100%; padding:14px; font-weight:800; font-size:12px;">🚀 EXPLAIN IT!</button>
    <button class="btn-secondary" style="margin-top:14px;" onclick="showHome()">← HOME</button>
  `;
  out.appendChild(container);
  var resultsDiv = document.createElement("div");
  resultsDiv.id = "eli5Results";
  resultsDiv.className = "hidden slide-in";
  resultsDiv.style.cssText = "margin: 15px; padding: 20px; background: white; border: 1px solid #cfd8dc; border-top: 5px solid #2e7d32; box-shadow: 0 4px 10px rgba(0,0,0,0.05);";
  out.appendChild(resultsDiv);
  var slider = document.getElementById("eli5Slider");
  var display = document.getElementById("eli5AgeDisplay");
  var desc = document.getElementById("eli5Desc");
  var descriptions = {
    10: "Simplifies everything into analogies and basic sentences. Removes all jargon.",
    14: "Explains concepts clearly using standard language. Defines complex terms.",
    18: "Professional but accessible summary. Removes unnecessary legalese but keeps nuance.",
  };
  slider.oninput = function () {
    display.innerText = this.value;
    desc.innerText = descriptions[this.value] || descriptions["14"];
  };
  var detailSlider = document.getElementById("eli5DetailSlider");
  var detailLabel = document.getElementById("eli5DetailLabel");
  var detailMap = { 1: "Standard", 2: "Enhanced", 3: "Deep Dive" };
  detailSlider.oninput = function () {
    detailLabel.innerText = detailMap[this.value];
  };
  window.toggleEli5Source = function (mode) {
    var upArea = document.getElementById("eli5UploadArea");
    var radios = document.getElementsByName("eli5Source");
    if (mode === "upload") {
      upArea.classList.remove("hidden");
      radios[1].checked = !0;
      radios[1].parentElement.style.background = "#e3f2fd";
      radios[1].parentElement.style.borderColor = "#2196f3";
      radios[0].parentElement.style.background = "#f5f5f5";
      radios[0].parentElement.style.borderColor = "#ddd";
    } else {
      upArea.classList.add("hidden");
      radios[0].checked = !0;
      radios[0].parentElement.style.background = "#e3f2fd";
      radios[0].parentElement.style.borderColor = "#2196f3";
      radios[1].parentElement.style.background = "#f5f5f5";
      radios[1].parentElement.style.borderColor = "#ddd";
    }
  };
  window.toggleEli5Detail = function () {
    var body = document.getElementById("eli5DetailBody");
    var arrow = document.getElementById("eli5DetailArrow");
    if (body.classList.contains("hidden")) {
      body.classList.remove("hidden");
      arrow.innerText = "▲";
    } else {
      body.classList.add("hidden");
      arrow.innerText = "▼";
    }
  };
  var dropZone = document.getElementById("eli5UploadArea");
  var fileInp = document.getElementById("eli5FileInput");
  var nameDisplay = document.getElementById("eli5FileName");
  var uploadedPayload = null;
  dropZone.onclick = () => fileInp.click();
  fileInp.onchange = function (e) {
    var file = e.target.files[0];
    if (!file) return;
    nameDisplay.innerText = "⏳ Reading " + file.name + "...";
    handleFileSelect(file, function (textPayload, htmlPayload) {
      if (typeof textPayload === "object" && textPayload.isBase64) {
        uploadedPayload = textPayload;
      } else {
        uploadedPayload = textPayload;
      }
      nameDisplay.innerHTML = "✅ <strong>" + file.name + "</strong> ready.";
      dropZone.style.backgroundColor = "#e8f5e9";
      dropZone.style.borderColor = "#2e7d32";
    });
  };
  document.getElementById("btnRunEli5").onclick = function () {
    var age = slider.value;
    var detail = detailSlider.value;
    var mode = document.querySelector('input[name="eli5Source"]:checked').value;
    if (mode === "upload" && !uploadedPayload) {
      showToast("⚠️ Please upload a file first.");
      return;
    }
    runEli5Analysis(age, detail, mode, uploadedPayload);
  };
}

functions.runEli5Analysis:
async function runEli5Analysis(age, detailLevel, mode, uploadData) {
  setLoading(!0);
  var out = document.getElementById("eli5Results");
  out.classList.add("hidden");
  try {
    var contextText = "";
    var isPdf = !1;
    if (mode === "upload") {
      if (uploadData.isBase64) {
        contextText = uploadData;
        isPdf = !0;
      } else {
        contextText = uploadData;
      }
    } else {
      contextText = await validateApiAndGetText(!1, null);
    }
    var persona = "";
    var instructions = "";
    if (age == "10") {
      persona = getPrompt("explainPersonaChild");
      instructions = getPrompt("explainInstructionsChild");
    } else if (age == "14") {
      persona = getPrompt("explainPersonaTeen");
      instructions = getPrompt("explainInstructionsTeen");
    } else {
      persona = getPrompt("explainPersonaAdult");
      instructions = getPrompt("explainInstructionsAdult");
    }
    var detailInstruction = "";
    if (detailLevel == "2") {
      detailInstruction =
        "Provide a comprehensive explanation. For every key point, add a sentence explaining 'Why this matters'. Expand on the definitions.";
    } else if (detailLevel == "3") {
      detailInstruction =
        "Provide an exhaustive, deep-dive explanation. Leave no concept unexplained. Include a specific 'Example Scenario' for the main topics to illustrate how they work in real life. Ensure the reader walks away with expert-level understanding (but in simple language).";
    } else {
      detailInstruction = "Keep it concise and to the point. Focus only on the most critical information.";
    }
    var prompt = `
        ${persona}
        TASK: Explain this document content (whether a Legal Agreement or Scientific Publication) to an audience of age ${age}.
        GUIDELINES:
        1. ${instructions}
        2. DEPTH: ${detailInstruction}
        3. STRUCTURE:
           - **The Gist:** A summary of what this document is about.
           - **Key Points:** Bullet points of the most important concepts or rules.
           - **Why It Matters:** The impact, risks, or conclusions.
           ${detailLevel == "3" ? "- **Real World Example:** A hypothetical scenario illustrating the concept." : ""}
        4. FORMAT: Use HTML formatting (<b>, <ul>, <li>, <br>). Do NOT use Markdown blocks.
        DOCUMENT CONTENT:
    `;
    var parts = [];
    if (isPdf) {
      parts = [{ text: prompt }, { inlineData: { mimeType: "application/pdf", data: contextText.data } }];
    } else {
      parts = [{ text: prompt + "\n\n" + contextText.substring(0, 500000) }];
    }
    var response = await callGemini(API_KEY, parts);
    if (!response) {
      setLoading(!1);
      showCancelledState();
      return;
    }
    setLoading(!1);
    out.classList.remove("hidden");
    var cleanHtml = response
      .replace(/```html/g, "")
      .replace(/```/g, "")
      .replace(/\*\*(.*?)\*\*/g, "<b>$1</b>")
      .replace(/>\s*[\r\n]+\s*/g, ">")
      .replace(/\n{2,}/g, "\n")
      .replace(/\n/g, "<br>");
    out.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:15px; padding-bottom:10px; border-bottom:1px dashed #ccc;">
            <div style="font-size:12px; font-weight:800; color:#2e7d32; text-transform:uppercase;">EXPLANATION (Age ${age})</div>
            <button onclick="navigator.clipboard.writeText(this.parentElement.nextElementSibling.innerText); showToast('Copied text')" style="background:none; border:none; color:#90a4ae; cursor:pointer; font-size:12px;">📋 Copy</button>
        </div>
        <div style="font-family:'Segoe UI', sans-serif; font-size:14px; line-height:1.5; color:#37474f;">
            ${cleanHtml}
        </div>
    `;
    out.scrollIntoView({ behavior: "smooth", block: "nearest" });
  } catch (e) {
    setLoading(!1);
    if (e.message && (e.message.includes("cancelled") || e.message.includes("AbortError"))) {
      showCancelledState();
    } else {
      showToast("❌ Error: " + e.message);
    }
  }
}
